WITH latest AS (SELECT id, reading_ts, temp_c, humidity, status_bits, firmware FROM device_readings QUALIFY ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts DESC, id ASC) = 1) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, APPROX_PERCENTILE(status_bits, 0.5) AS status_bits_p50, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, PERCENTILE_APPROX(status_bits, 0.9) AS status_bits_p90, STDDEV_SAMP(humidity) AS humidity_stddev FROM latest GROUP BY DATE_TRUNC('HOUR', reading_ts) ORDER BY humidity_stddev ASC;
